head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.g_ACPT_NO = '';
scwin.gSDate;
scwin.gEDate;
scwin.gSTimer;
scwin.gETimer;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80235.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await scwin.alert_error2(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_List.removeAll();
        }
        textbox_1.setValue("총 " + rowcount + "건");
        scwin.dispTimer(textbox_1); // 경과시간 표시

        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadError
 * @description dts_List2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List2_OnLoadError = async function() {
    try {
        await scwin.alert_error2(dts_List2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_List2.removeAll();
        }
        textbox_2.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(dts_List, row);
        if (colid === 'DOC_TITLE') {
            fn_OpenDisclViewer_MGT(scwin.g_ACPT_NO, 'ULDMGT80235.xml');
        } else if (colid !== 'DOC_TITLE' && colid !== 'ACPT_NO') {
            // 팝업 오픈
            await scwin.popupSchdlExtrcOpen();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT80235.grd_List_OnDblClick" });
    }
};

