 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_Date);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.img_FromCal_onclick" });
