};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function() {
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    scwin.gSDate = new Date();
    scwin.gSTimer = scwin.gSDate.getTime();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name list2
 * @description list2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list2 = async function() {
    const sbmOptions = {
        id : "sbm_dts_List2",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    edt_Date.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};

/**
 * @method
 * @name validDateTodayCheck
 * @description valid Date Today Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.validDateTodayCheck = function() {
    return true;
};

/**
 * @method
 * @name validCheck
 * @description valid Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    if (getObjectValue(edt_Date).length < 8) {
        await $c.win.alert("[추출일자]를 올바르게 입력하세요.");
        edt_Date.focus();
        return false;
    }
    if (getObjectValue(edt_StartTm).length < 4) {
        await $c.win.alert("[추출시간]을 올바르게 입력하세요.");
        edt_StartTm.focus();
        return false;
    }
    if (getObjectValue(edt_EndTm).length < 4) {
        await $c.win.alert("[추출시간]을 올바르게 입력하세요.");
        edt_EndTm.focus();
        return false;
    }
    if (getObjectValue(edt_StartTm) > getObjectValue(edt_EndTm)) {
        await $c.win.alert("[시작시간]을 [종료시간] 이전으로 선택하세요.");
        edt_StartTm.focus();
        return false;
    }
    if (getObjectValue(txb_ACPT_NO) !== "" && getObjectValue(txb_ACPT_NO).length !== 14) {
        await $c.win.alert("[접수번호]를 올바르게 입력하세요.");
        txb_ACPT_NO.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (!await scwin.validCheck()) {
        return;
    }
    await scwin.list(); // 공시서식,상장서식,조건추출

    await scwin.list2(); // 배치,화면

};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj, row) {
    scwin.g_ACPT_NO = obj.getCellData(Number(row), "ACPT_NO");
};

/**
 * @method
 * @name popupSchdlExtrcOpen
 * @description popup Schdl Extrc Open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popupSchdlExtrcOpen = async function() {
    const usrp = "/sysmonitor/ULDMGT80236.gfm";
    const winTitle = "일정추출 상세";
    await $c.frame.CreateDialogFrame("viewer_pop", usrp, winTitle, 0, -120, 1352, 1000, "window");
    // frame.Provider('/').OuterWindow.window.open(usrp,  "viewer_pop",
    //        "left=0,top=0,width=1750,height=965,resizable=yes,scrollbars=no,location=no,status=no");

};

/**
 * @method
 * @name dispTimer
 * @description disp Timer 처리
 * @param {*} textbox textbox
 * @returns {void}
 * @hidden N
 */
scwin.dispTimer = function(textbox) {
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    const dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    const min = Math.round(dispTimer / 60, 2);
    const sec = Math.round(dispTimer % 60);

    // alert("처리시간 : " + min + " 분 " + sec + "초");

    textbox.setValue(textbox.getValue() + " (처리시간 : " + min + " 분 " + sec + "초)");
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
